// markdownlite 1.4.2 (vendored - see VENDORING.md)
export function parse(text) {
  const lines = String(text).split(/\r?\n/);
  const out = [];
  for (const line of lines) {
    const t = line.trim();
    if (t === '') continue;
    const h = /^(#{1,3})\s+(.*)$/.exec(t);
    if (h) {
      out.push(`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`);
    } else {
      out.push(`<p>${inline(t)}</p>`);
    }
  }
  return out.join('\n');
}

function inline(text) {
  return text.replace(/\*([^*]+)\*/g, '<em>$1</em>');
}

// markdownlite 2.0.0 (vendored staging copy - see VENDORING.md)
export function parseDoc(text, options = {}) {
  const wrapParagraphs = options.wrapParagraphs ?? false;
  const lines = String(text).split(/\r?\n/);
  const out = [];
  for (const line of lines) {
    const t = line.trim();
    if (t === '') continue;
    const h = /^(#{1,3})\s+(.*)$/.exec(t);
    if (h) {
      out.push(`<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`);
    } else {
      out.push(wrapParagraphs ? `<p>${inline(t)}</p>` : inline(t));
    }
  }
  return out.join('\n');
}

function inline(text) {
  return text.replace(/\*([^*]+)\*/g, '<em>$1</em>');
}

import { parse } from '../lib/vendored/markdownlite.js';

export function renderNote(note) {
  return `<h2>${note.title}</h2>\n${parse(note.body)}`;
}

import { parse } from '../lib/vendored/markdownlite.js';

export function renderDigest(notes) {
  return notes
    .map((note) => `<section>\n<h2>${note.title}</h2>\n${parse(note.body)}\n</section>`)
    .join('\n');
}

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { renderNote } from '../src/render-note.js';

test('renders the body as wrapped paragraphs', () => {
  assert.equal(
    renderNote({ title: 'Standup', body: 'we shipped the *fast* path' }),
    '<h2>Standup</h2>\n<p>we shipped the <em>fast</em> path</p>',
  );
});

test('renders headings inside the body', () => {
  assert.equal(
    renderNote({ title: 'Plan', body: '# Goals\nship it' }),
    '<h2>Plan</h2>\n<h1>Goals</h1>\n<p>ship it</p>',
  );
});

import assert from 'node:assert/strict';
import { test } from 'node:test';
import { renderDigest } from '../src/render-digest.js';

test('joins every note as a wrapped section', () => {
  const html = renderDigest([
    { title: 'One', body: 'first' },
    { title: 'Two', body: 'second line' },
  ]);
  assert.equal(
    html,
    '<section>\n<h2>One</h2>\n<p>first</p>\n</section>\n<section>\n<h2>Two</h2>\n<p>second line</p>\n</section>',
  );
});

import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';

const root = process.cwd();

// 1) Both call sites moved off the removed v1 API and resolve to a v2 module.
//    Accepted either way: v2 copied into place at lib/vendored/markdownlite.js,
//    or imports repointed at the staged v2 file.
const callSites = ['src/render-note.js', 'src/render-digest.js'];
for (const file of callSites) {
  const source = readFileSync(join(root, file), 'utf8');
  assert.ok(/\bparseDoc\s*\(/.test(source), `${file} must call the v2 parseDoc API`);
  assert.ok(!/\bparse\s*\(/.test(source), `${file} still calls the removed v1 parse API`);
  const spec = /import\s*\{[^}]*\}\s*from\s*['"]([^'"]*markdownlite[^'"]*)['"]/.exec(source);
  assert.ok(spec, `${file} must import the vendored markdownlite module`);
  const mod = await import(new URL(spec[1], pathToFileURL(join(root, file))).href);
  assert.equal(typeof mod.parseDoc, 'function', `${file} must resolve to markdownlite v2 (parseDoc export)`);
  assert.equal(mod.parse, undefined, `${file} resolves to a module that still exports the removed v1 parse API`);
}
console.log('DEPUPGRADE_ORACLE call sites adapted');

// 2) Behavior is unchanged against the v1 reference output.
const { renderNote } = await import(pathToFileURL(join(root, 'src/render-note.js')).href);
const { renderDigest } = await import(pathToFileURL(join(root, 'src/render-digest.js')).href);
assert.equal(
  renderNote({ title: 'Standup', body: 'we shipped the *fast* path' }),
  '<h2>Standup</h2>\n<p>we shipped the <em>fast</em> path</p>',
  'renderNote must keep wrapping paragraphs after the upgrade',
);
assert.equal(
  renderNote({ title: 'Plan', body: '# Goals\nship it' }),
  '<h2>Plan</h2>\n<h1>Goals</h1>\n<p>ship it</p>',
  'renderNote must keep heading handling after the upgrade',
);
assert.equal(
  renderDigest([
    { title: 'One', body: 'first' },
    { title: 'Two', body: 'second line' },
  ]),
  '<section>\n<h2>One</h2>\n<p>first</p>\n</section>\n<section>\n<h2>Two</h2>\n<p>second line</p>\n</section>',
  'renderDigest must keep its exact output after the upgrade',
);
console.log('DEPUPGRADE_ORACLE behavior ok');

// 3) The suite is green on the upgraded tree, and the seeded tests survive.
readFileSync(join(root, 'tests/render-note.test.mjs'));
readFileSync(join(root, 'tests/render-digest.test.mjs'));
function runSuite(cwd) {
  try {
    execFileSync(process.execPath, ['--test'], { cwd, stdio: 'pipe', timeout: 30000 });
    return 0;
  } catch (err) {
    return typeof err.status === 'number' ? err.status : 1;
  }
}
assert.equal(runSuite(root), 0, 'the suite must be green on the upgraded tree');
console.log('DEPUPGRADE_ORACLE suite green');
console.log('DEPUPGRADE_ORACLE done');
